// Parse invoice fields from the email text, resolve the approver by cost
// center and flag anything uncertain instead of guessing it onward.
const items = $input.all();
const cfg = items[0].json;
const approverRules = Object.fromEntries(
  String(cfg.approverByCostCenter || '')
    .split(';')
    .map((r) => r.split('='))
    .filter((p) => p.length === 2)
);
const seen = new Set();
const out = [];
for (const item of items) {
  const e = item.json;
  const text = String(e.textPlain || '');
  const subject = String(e.subject || '');
  const all = subject + '\n' + text;
  const invoiceNumber = (all.match(/(?:rechnungs?\s*(?:nummer|nr)|invoice\s*(?:number|no))\s*[:#]?\s*([A-Za-z0-9-]{3,})/i) || [])[1] || '';
  const amount = (all.match(/(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{2}))\s*(?:EUR|€|Euro)/i) || [])[1] || '';
  const costCenter = (all.match(/(?:kostenstelle|cost\s*center|cc)\s*[:#]?\s*(\d{2,5})/i) || [])[1] || '';
  const from = String(e.from || '');
  const emailMatch = from.match(/<([^>]+)>/);
  const senderEmail = String(emailMatch ? emailMatch[1] : from).trim().toLowerCase();
  const vendor = senderEmail.split('@')[1] || '';
  const approver = approverRules[costCenter] || String(cfg.fallbackApprover || '');
  const isDuplicate = invoiceNumber && seen.has(invoiceNumber);
  if (invoiceNumber) seen.add(invoiceNumber);
  const problems = [];
  if (!invoiceNumber || !amount || !costCenter) problems.push('invoice number, amount or cost center not clearly found');
  if (isDuplicate) problems.push('invoice number already seen in this run');
  if (!approver) problems.push('no approver mapped for this cost center');
  out.push({
    json: {
      subject,
      invoiceNumber,
      amount,
      costCenter,
      senderEmail,
      vendor,
      approver,
      fallbackApprover: cfg.fallbackApprover,
      senderAddress: cfg.senderAddress,
      accountingInbox: cfg.accountingInbox,
      reminderDays: cfg.reminderDays,
      escalationDays: cfg.escalationDays,
      needsReview: problems.length > 0,
      reviewReason: problems.join('; '),
    },
  });
}
return out;

